{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment <= 0.00) to counteract overestimation bias.",
    "Reduce forecast magnitude by 5-10% if recent true outcomes show mean reversion toward lower prices after spikes.",
    "Increase forecast lag by 1-2 days if sentiment is positive (sentiment > 0.00) to avoid premature overshoots.",
    "Apply upward correction if true outcome exceeds forecast by >15% and sentiment is neutral — signal potential market overreaction.",
    "If forecast consistently underestimates true outcome in 3+ consecutive days, increase forecast baseline by 3-5% to account for persistent bullish momentum.",
    "When sentiment is positive and forecast is below historical 30-day mean, consider adding a 2-3% upward bias to align with sentiment-driven momentum."
  ]
}
